"""Document this scoped art revision without rewriting unrelated model metadata."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'godot/assets/models/station_props'
report=json.loads((OUT/'volume_rebuild_validation.json').read_text())
models=json.loads((OUT/'model_info.json').read_text())
lines=['# Volume reconstruction: generator, disposal and portable tanks','',
'This revision replaces the 13 individual BLEND/GLB files listed below. Open `machinery_and_tanks_library.blend` for the current editable models and `machinery_and_tanks_preview.blend` for the preview. The old general station library and its images predate this revision; use these new files for this batch. Stationary tank files are untouched.','',
'The original sprites are oblique references, not frontal photographs. Generator jackets now have full depth, stepped shoulders, vents and coil geometry. Chemical trolleys contain two cylindrical vessels with bands and supports. Portable canisters have circumferential barrel UVs, stepped shoulders, a regulator, bridge handle and separate pressure knob. The disposal has a closed shell and a lined, deep hopper. Unseen sides are reconstructions from the visible construction and source palette.','',
'All structural bodies are connected, manifold solids with internal intersections removed. Working controls and hatches retain separate pivots. Each part has one material in slot 0, named `Surface_<model>`. The nine portable variants share their actual Blender mesh data; water/fuel geometry is shared as well. Flat shading and nearest filtering are retained.','',
'Original PNGs are unchanged. Thirteen separate 64 × 64 derived surface sheets are stored in `textures/*_surfaces.png`. Each sheet contains sixteen 16 × 16 cells. `surface_rebuild_recipes.json` records the source state and pixel rectangles. Source fragments are sampled with nearest filtering; circumference patches use reflected repetition, and transparent silhouette margins use the nearest opaque source texel. Top, bottom, side, band and control surfaces have their own UV regions. The disposal lever is physical geometry, so its printed duplicate is removed from the derived front patch. No AI-generated image textures were used.','',
'Validation: 13 GLBs, 11,128 instantiated triangles, 111,280 opaque UV samples, no transparent pixel hits, no degenerate triangles, no collapsed UV triangles, positive volumes and manifold edges/vertices. Each exported part has one connected component. The models were inspected from front, right, back, three-quarter, top and bottom views (top/bottom by geometry family). No animations, collisions or gameplay integration were added. Godot runtime/import remains untested.','',
'The Godot preview is `previews/machinery_and_tanks_preview.tscn`, relative to the independent `project.godot` in this directory.','',
'## Models','', '| Model | Triangles | Dimensions XYZ (m) |','|---|---:|---|']
for key,r in report.items():lines.append(f"| [{key}]({models[key]['file']}) | {r['triangles']} | {' × '.join(map(str,r['dimensions_m']))} |")
lines+=['','## Review sheets','','See `docs/ai/art/quality/machinery_and_tanks.png`, `tank_variants_1.png`, and `tank_variants_2.png`. Original references are in `docs/ai/art/machinery_and_tanks_reference.png`.','','## Reproduction','','In the existing Blender builder session, run `tools/art/rebuild_round_props.py`, inspect the models, then run `tools/art/export_round_props.py`. The scripts use the live `station_props_build` namespace and affect only this batch. Run `python tools/art/validate_station_props.py --volume-only` for independent GLB checks. Do not run the older full-library builder to reproduce this batch: it contains the superseded shapes.','','Backups of replaced individual files are under `backups/before_volume_rebuild_*/`.']
(OUT/'machinery_and_tanks.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
scene=['[gd_scene load_steps=15 format=3]','']
for i,k in enumerate(report,1):scene.append(f'[ext_resource type="PackedScene" path="res://{models[k]["file"]}" id="{i}"]')
scene+=['','[sub_resource type="Environment" id="Environment"]','background_mode = 1','background_color = Color(0.055, 0.07, 0.09, 1)','ambient_light_source = 3','ambient_light_color = Color(0.7, 0.75, 0.8, 1)','ambient_light_energy = 0.7','','[node name="RebuiltVolumePreview" type="Node3D"]','','[node name="Environment" type="WorldEnvironment" parent="."]','environment = SubResource("Environment")','','[node name="Sun" type="DirectionalLight3D" parent="."]','rotation_degrees = Vector3(-55, -30, 0)','light_energy = 1.1','','[node name="Camera" type="Camera3D" parent="."]','position = Vector3(2.25, 7, 11)','rotation_degrees = Vector3(-35, 0, 0)','current = true','projection = 1','size = 9.5']
for i,k in enumerate(report):scene+=['',f'[node name="{k}" parent="." instance=ExtResource("{i+1}")]' ,f'position = Vector3({i%4*1.5}, 0, {i//4*1.7})']
(OUT/'previews/machinery_and_tanks_preview.tscn').write_text('\n'.join(scene)+'\n')
print('Documented 13 rebuilt models and standalone preview.')
